<template>
  <div class="change-route">
    <!-- <title-line :title="title" /> -->
    <div class="upgradeImg" />
    <div class="line-text">抱歉，由于网络原因无法正常
      打开游戏网址</div>
    <div class="ip-text">您的ip地址：{{ ipText }}</div>
    <div class="split-line" />
    <span class="tip-text">请切换<div class="change-btn" @click="changeRoute()">{{ routeName }}</div>试试，若您长时间</span>
    <div class="tip-text-second">无法正常使用，您可以<span class="tip-main" @click="showService=true">{{ '【联系客服】' }}</span></div>
    <van-popup v-model="showService">
      <customer-service :is-route="true" @close="showService=false" />
    </van-popup>
  </div>
</template>
<script>
// import TitleLine from './modules/TitleLine'
import CustomerService from './modules/CustomerService.vue'
export default {
  components: {
    // TitleLine
    CustomerService
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      routeName: '线路2',
      showService: false,
      title: '升级中',
      interval: null,
      ipText: ''
    }
  },
  created() {
    if (localStorage.getItem('route') && localStorage.getItem('route') === '线路2') {
      this.routeName = '线路1'
    } else {
      this.routeName = '线路2'
    }
    // const ip=window.location.hostname
    // const ip1=navigator.connection
    fetch('https://api64.ipify.org?format=json').then(response => response.json()).then(data => {
      this.ipText = data.ip
      console.log(data.ip)
    }).catch(error => console.error(error))
  },
  async mounted() {
    // this.getLocalIP().then(ip => {
    //   this.ipText = ip
    //   console.log('Local IP Address:', ip)
    // })
  },
  beforeDestroy() {
    if (this.interval) {
      clearInterval(this.interval)
    }
  },
  methods: {
    getLocalIP(onNewIP) {
      return new Promise(resolve => {
        const RTCPeerConnection = window.RTCPeerConnection ||
            window.mozRTCPeerConnection ||
            window.webkitRTCPeerConnection
        if (!RTCPeerConnection) {
          console.log('Browser does not support webRTC')
          return
        }
        const pc = new RTCPeerConnection({ iceServers: [] })
        pc.createDataChannel('')
        pc.onicecandidate = (event) => {
          if (event.candidate) {
            const ipRegex = /([0-9]{1,3}(\.[0-9]{1,3}){3})/
            const ipAddress = event.candidate.candidate.match(ipRegex)
            if (ipAddress && ipAddress[1] !== '192.0.0.1' && ipAddress[1] !== '127.0.0.1') {
              resolve(ipAddress[1])
              pc.onicecandidate = null
              pc.close()
            }
          }
        }
        pc.createOffer().then((sdp) => {
          sdp.sdp.split('\n').forEach((line) => {
            if (line.indexOf('a=candidate') === 0) {
              pc.addIceCandidate(
                new RTCIceCandidate({ candidate: line, sdpMLineIndex: null, sdpMid: '' }),
                () => {},
                () => {}
              )
            }
          })
        })
        pc.createOffer((description) => {
          pc.setLocalDescription(description, () => {}, () => {})
        }, () => {})
      })
    },
    changeRoute() {
      localStorage.setItem('route', this.routeName)
      this.$router.push('/home')
    }
  }

}
</script>
